INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(104357, 'ruRU', '', 'Радж''кесс... убей это...', 24330),
(104358, 'ruRU', '', 'Sakar''thiss...', 24330),
(104364, 'ruRU', '', 'Магус Солнечный Взор, зарядите кристалл портала.', 24330),
(104371, 'ruRU', '', 'Он увядает...', 24330),
(104372, 'ruRU', '', 'Я подобрала ещё несколько кристаллов маны, пока тебя не было. Положи его сюда.', 24330),
(104376, 'ruRU', '', 'Эта магия Скверны пожирает мою душу! Я не могу долго удерживать портал открытым. Вперёд!', 24330),
(104384, 'ruRU', '', 'Эта жажда Ночного Колодца бесконечна. Если бы я не повстречала Маношейла, то уже давно бы погибла.', 24330),
(104385, 'ruRU', '', 'Я довольна, проводя свои дни здесь внизу с Маношейлом. Он быстро становится моим самым близким другом.', 24330),
(104411, 'ruRU', '', 'Наконец-то свободен от этой проклятой магической ловушки! Что за-', 24330),
(104413, 'ruRU', '', 'Погодите, я узнаю этот голос...', 24330),
(104415, 'ruRU', '', 'МИЛХАУС!! Ты следующий!', 24330),
(104419, 'ruRU', '', 'Ах ты... Никто не оскорбляет мои волосы! НИКТО!', 24330),
(104422, 'ruRU', '', 'Я знаю, это был ты, Милхаус!', 24330),
(104425, 'ruRU', '', 'Не смей звать меня "Милли", Милхаус Джеримус Манашторм! Я иду за тобой!', 24330),
(104447, 'ruRU', '', 'Спасибо, $c. Мне нужно вернуться к сёстрам.', 24330),
(104448, 'ruRU', '', 'Моя благодарность, защитник! Теперь нужно разобраться с теми мерзкими дрогбарами, что нас поймали.', 24330),
(104449, 'ruRU', '', 'Как же здорово снова тебя видеть, $n! Мы ведь неплохо подпалили Пандарию вместе, да?$b$bЯ оттачивала свои огненные заклинания с тех пор, как ты в последний раз работал с Шадо-Пан. Если сможешь удержать меня на ногах, я смогу пробить ледяные стены Асперсия и в остальном довести его до кипения. Встань рядом со мной, и я усилю мощь твоей Нефритовой молнии.$b$b<Фей Ли свирепо ухмыляется.>$b$bХочешь, чтобы я НАСТОЯЩЕ его подпалила, или мне стоит сосредоточиться на том, чтобы остаться в живых?', 24330),
(104450, 'ruRU', '', 'Спасибо, $c, что пришёл к нам на помощь. Я Фей Ли, и у меня репутация в Шадо-Пан — поджигательница вещей. Обычно наших врагов. Иногда — нашего монастыря. Лорд Таран Чжу сейчас не слишком мной доволен...$b$bПомоги мне вернуть его расположение. Если сможешь удержать меня на ногах, я смогу пробить ледяные стены Асперсия и в остальном довести его до кипения. Встань рядом со мной, и моя Аура Сияния восстановит твою ману.$b$b<Фей Ли свирепо ухмыляется.>$b$bХочешь, чтобы я НАСТОЯЩЕ его подпалила, или мне стоит сосредоточиться на том, чтобы остаться в живых?', 24330),
(104458, 'ruRU', '', '$n! Прошло столько времени. Тебе стоит навещать нас в Пандарии почаще. Мы с тобой были отличной командой.$b$bТы знаешь мои сильные стороны, $n. Пока Таран Чжу удерживает внимание этой твари, я подкрадусь к ней сзади и вонжу кинжалы в любые слабые места. Я также могу помочь тебе быстро передвигаться по полю боя — встань рядом со мной, чтобы сбросить перезарядку кувырка и удара в прыжке.$b$bНасколько агрессивной мне быть? Я могла бы отбросить осторожность и пойти в тотальное наступление, но мне нужно знать, что ты меня прикроешь!', 24330),
(104459, 'ruRU', '', 'Спасибо за своевременное спасение, $c. Нам бы пригодилась твоя помощь в Пандаренской кампании. Меня зовут Таоши, безмолвный клинок Шадо-Пан. Я незаметно проскальзываю по вражеской территории и бью туда, где они слабее всего.$b$bЯ сделаю свою часть работы. Пока Таран Чжу удерживает внимание этой твари, я подкрадусь к ней сзади и вонжу кинжалы в любые слабые места. Я также могу помочь тебе быстро передвигаться по полю боя — встань рядом со мной, чтобы получить заряды Кувырка, Торпеды Ци и Шага сквозь туман.$b$bНасколько агрессивным мне быть? Я мог бы отбросить осторожность и пойти в тотальное наступление, но мне нужно знать, что ты меня прикроешь!', 24330),
(104469, 'ruRU', '', 'Если оно лжёт, мы снесём ему голову. Но если есть хоть малейший шанс, что оно говорит правду, нам стоит попробовать!', 24330),
(104470, 'ruRU', '', 'Пссс! Сюда, $n.', 24330),
(104482, 'ruRU', '', 'Я чувствую силу лей-линии.', 24330),
(104483, 'ruRU', '', 'Ты не навредишь нашим растениям!', 24330),
(104484, 'ruRU', '', 'Ты оскверняешь нашу среду обитания!', 24330),
(104485, 'ruRU', '', 'Незваный гость!', 24330),
(104486, 'ruRU', '', 'Мои растения...', 24330),
(104487, 'ruRU', '', 'Сёстры!', 24330),
(104488, 'ruRU', '', 'Идите ко мне, сёстры мои...', 24330),
(104489, 'ruRU', '', 'Я должна... защищать...', 24330),
(104490, 'ruRU', '', 'Замри и дай мне залечить твои раны.', 24330),
(104491, 'ruRU', '', 'Тебе повезло остаться в живых, сестра моя.', 24330),
(104492, 'ruRU', '', 'Отдыхай спокойно. Я позабочусь о тебе.', 24330),
(104493, 'ruRU', '', 'Угх...', 24330),
(104494, 'ruRU', '', 'Прошу... помогите мне...', 24330),
(104495, 'ruRU', '', 'Не бросайте меня вот так...', 24330),
(104496, 'ruRU', '', 'Почему ты обратился против нас?', 24330),
(104506, 'ruRU', '', 'Ты заплатишь за то, что сделал, исчадие!', 24330),
(104509, 'ruRU', '', 'Слабый и жалкий! Сумеречный Отец не осмелился владеть мной, ибо знал цену неудачи.', 24330),
(104511, 'ruRU', '', 'А вот ты, с другой стороны... Да, я предвижу, что мы свершим вместе великие дела. Возьмись за моё древко, и я помогу тебе... пока что.', 24330);
